sys_script_include.script:
var getWalkUpLocation = Class.create();
getWalkUpLocation.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getWalkupLocName: function() {

        try {

            var incID = this.getParameter('sysparm_incID');

            var getIncDetails = new GlideRecord('incident');
            getIncDetails.get(incID);
            var incAssignmnetGrp = getIncDetails.assignment_group.getDisplayValue().toLowerCase();
            var incChannel = getIncDetails.contact_type.getDisplayValue().toLowerCase();

            if ((incAssignmnetGrp.indexOf('walk') > -1) || (incChannel.indexOf('walk') > -1)) {

                var getInterationRec = new GlideRecord('interaction_related_record');
                getInterationRec.addEncodedQuery('document_id=' + incID);
                getInterationRec.orderBy('sys_created_on');
                getInterationRec.setLimit(1);
                getInterationRec.query();

                if (getInterationRec.next()) {
                    var interactionRec = getInterationRec.interaction.sys_id;
                    var getInteractionLoc = new GlideRecord('interaction');
                    getInteractionLoc.get(interactionRec);
                    var interactionLoc = getInteractionLoc.location.sys_id;
                    var getWalkUpLoc = new GlideRecord('wu_location_queue');
                    getWalkUpLoc.addEncodedQuery('location.sys_idSTARTSWITH' + interactionLoc);
                    getWalkUpLoc.query();
                    if (getWalkUpLoc.next()) {
                        return getWalkUpLoc.sys_id;

                    }
                }


            }
        } catch (ex) {

        }



    },
    type: 'getWalkUpLocation'
});
